import { test, expect, Page } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { DashboardPage } from '../pages/DashboardPage';
import { OTPPage } from '../pages/OTPPage';
import { BankingLoginTestData } from '../test-data/BankingLoginTestData';

test.describe('Banking Login Test Suite', () => {
  
  // ========== SETUP ==========
  test.beforeEach(async ({ page, loginPage, dashboardPage, otpPage, testData }) => {
    // Navigate to login page
    await page.goto(process.env.BASE_URL ?? 'https://banking.example.com/login');
    
    // Verify login page is loaded
    await loginPage.validate();
  });

  // ========== TEARDOWN ==========
  test.afterEach(async ({ page }, testInfo) => {
    // Capture screenshot on failure
    if (testInfo.status !== testInfo.expectedStatus) {
      await page.screenshot({ 
        path: `screenshots/${testInfo.title}-${Date.now()}.png` 
      });
    }
  });

  // ========== TEST CASES ==========

  // TC_001: Login with valid username & password
  test('TC_001: Login with valid username & password', async ({ page, loginPage, dashboardPage, testData }) => {
    
    await test.step('Step 100 — Enter valid username', async () => {
      // Traceability: TC_001_STEP_02
      await loginPage.enterUsername(testData.validUser.username);
    });

    await test.step('Step 200 — Enter valid password', async () => {
      // Traceability: TC_001_STEP_03
      await loginPage.enterPassword(testData.validUser.password);
    });

    await test.step('Step 300 — Click Login button', async () => {
      // Traceability: TC_001_STEP_04
      await loginPage.clickLogin();
    });

    await test.step('Step 400 — Verify user redirected to dashboard', async () => {
      // Traceability: TC_001_VER_01
      await expect(page).toHaveURL(/dashboard/);
      // Traceability: TC_001_VER_01
      await expect(dashboardPage.getDashboardLocator()).toBeVisible();
    });
  });

  // TC_002: Login with valid credentials + OTP
  test('TC_002: Login with valid credentials + OTP', async ({ page, loginPage, otpPage, dashboardPage, testData }) => {
    
    await test.step('Step 100 — Enter valid username', async () => {
      // Traceability: TC_002_STEP_01
      await loginPage.enterUsername(testData.validUser.username);
    });

    await test.step('Step 200 — Enter valid password', async () => {
      // Traceability: TC_002_STEP_01
      await loginPage.enterPassword(testData.validUser.password);
    });

    await test.step('Step 300 — Click Login button', async () => {
      // Traceability: TC_002_STEP_02
      await loginPage.clickLogin();
    });

    await test.step('Step 400 — Enter valid OTP', async () => {
      // Traceability: TC_002_STEP_03
      const otp = await testData.getValidOTP();
      await otpPage.enterOTP(otp);
    });

    await test.step('Step 500 — Submit OTP', async () => {
      // Traceability: TC_002_STEP_04
      await otpPage.clickSubmit();
    });

    await test.step('Step 600 — Verify user redirected securely', async () => {
      // Traceability: TC_002_VER_01
      await expect(page).toHaveURL(/dashboard/);
      // Traceability: TC_002_VER_01
      await expect(dashboardPage.getDashboardLocator()).toBeVisible();
    });
  });

  // TC_003: Invalid username
  test('TC_003: Invalid username', async ({ page, loginPage, testData }) => {
    
    await test.step('Step 100 — Enter invalid username', async () => {
      // Traceability: TC_003_STEP_01
      await loginPage.enterUsername(testData.invalidUser.username);
    });

    await test.step('Step 200 — Enter valid password', async () => {
      // Traceability: TC_003_STEP_01
      await loginPage.enterPassword(testData.validUser.password);
    });

    await test.step('Step 300 — Click Login button', async () => {
      // Traceability: TC_003_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Step 400 — Verify error message', async () => {
      // Traceability: TC_003_VER_01
      await expect(loginPage.getErrorMessageLocator()).toHaveText(testData.errorMessages.invalidCredentials);
    });
  });

  // TC_004: Invalid password
  test('TC_004: Invalid password', async ({ page, loginPage, testData }) => {
    
    await test.step('Step 100 — Enter valid username', async () => {
      // Traceability: TC_004_STEP_01
      await loginPage.enterUsername(testData.validUser.username);
    });

    await test.step('Step 200 — Enter invalid password', async () => {
      // Traceability: TC_004_STEP_01
      await loginPage.enterPassword(testData.invalidUser.password);
    });

    await test.step('Step 300 — Click Login button', async () => {
      // Traceability: TC_004_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Step 400 — Verify error message', async () => {
      // Traceability: TC_004_VER_01
      await expect(loginPage.getErrorMessageLocator()).toHaveText(testData.errorMessages.invalidCredentials);
    });
  });

  // TC_005: Both credentials invalid
  test('TC_005: Both credentials invalid', async ({ page, loginPage, testData }) => {
    
    await test.step('Step 100 — Enter invalid username', async () => {
      // Traceability: TC_005_STEP_01
      await loginPage.enterUsername(testData.invalidUser.username);
    });

    await test.step('Step 200 — Enter invalid password', async () => {
      // Traceability: TC_005_STEP_01
      await loginPage.enterPassword(testData.invalidUser.password);
    });

    await test.step('Step 300 — Click Login button', async () => {
      // Traceability: TC_005_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Step 400 — Verify login denied', async () => {
      // Traceability: TC_005_VER_01
      await expect(page).toHaveURL(/login/);
      // Traceability: TC_005_VER_01
      await expect(loginPage.getErrorMessageLocator()).toBeVisible();
    });
  });

  // TC_006: Empty username
  test('TC_006: Empty username', async ({ page, loginPage, testData }) => {
    
    await test.step('Step 100 — Leave username blank, enter password', async () => {
      // Traceability: TC_006_STEP_01
      await loginPage.enterPassword(testData.validUser.password);
    });

    await test.step('Step 200 — Click Login button', async () => {
      // Traceability: TC_006_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Step 300 — Verify validation message', async () => {
      // Traceability: TC_006_VER_01
      await expect(loginPage.getValidationMessageLocator()).toHaveText(testData.errorMessages.usernameRequired);
    });
  });

  // TC_007: Empty password
  test('TC_007: Empty password', async ({ page, loginPage, testData }) => {
    
    await test.step('Step 100 — Enter username, leave password blank', async () => {
      // Traceability: TC_007_STEP_01
      await loginPage.enterUsername(testData.validUser.username);
    });

    await test.step('Step 200 — Click Login button', async () => {
      // Traceability: TC_007_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Step 300 — Verify validation message', async () => {
      // Traceability: TC_007_VER_01
      await expect(loginPage.getValidationMessageLocator()).toHaveText(testData.errorMessages.passwordRequired);
    });
  });

  // TC_008: Both fields empty
  test('TC_008: Both fields empty', async ({ page, loginPage }) => {
    
    await test.step('Step 100 — Click Login without entering data', async () => {
      // Traceability: TC_008_STEP_01
      await loginPage.clickLogin();
    });

    await test.step('Step 200 — Verify required field validation', async () => {
      // Traceability: TC_008_VER_01
      await expect(loginPage.getValidationMessageLocator()).toBeVisible();
    });
  });

});